    @classmethod
    def get_disease(cls, orpha_code: str) -> Optional[RareDiseaseRecord]:
        cls.initialize()
        return cls._DATA.get(orpha_code.strip().upper())

    @classmethod
    def count(cls) -> int:
        cls.initialize()
        return len(cls._DATA)
